CREATE TEMP TABLE audit_events (LIKE public.audit_events INCLUDING ALL) ON COMMIT DROP;
CREATE OR REPLACE FUNCTION pg_temp.qa_queue_post(brand uuid) RETURNS jsonb LANGUAGE plpgsql AS $helper$
DECLARE p jsonb; cmd jsonb; snap jsonb; model jsonb;
BEGIN
 p:=pcs.content_action('create',jsonb_build_object('request_id',gen_random_uuid(),'brand_id',brand,'platform','telegram','language','en','title','Queue fixture','body','Approved queue fixture text','source_facts','Confirmed fixture business facts; never a real publication.','source_url','https://example.invalid/queue'),'pcs-manager-admin','["*"]');
 p:=pcs.content_action('submit',jsonb_build_object('request_id',gen_random_uuid(),'id',p->>'id','expected_version',p->'version'),'pcs-manager-admin','["*"]');
 cmd:=jsonb_build_object('request_id',gen_random_uuid(),'id',p->>'id','expected_version',p->'version');snap:=pcs.content_complete_duplicate_check(cmd,'pcs-manager-admin','["*"]',NULL)->'snapshot';
 model:=jsonb_build_object('outcome','NO_SIMILARITY_FOUND','matches','[]'::jsonb,'note','Synthetic fixture comparison, no provider called.','method',CASE WHEN (snap->>'corpus_count')::integer=0 THEN 'EMPTY_CORPUS' ELSE 'AI_SEMANTIC_COMPARISON' END);
 p:=pcs.content_complete_duplicate_check(cmd||jsonb_build_object('snapshot_signature',snap->>'snapshot_signature'),'pcs-manager-admin','["*"]',model);
 RETURN pcs.content_action('approve',jsonb_build_object('request_id',gen_random_uuid(),'id',p->>'id','expected_version',p->'version','revision',1,'facts_checked',true,'duplicate_review_note','Manually reviewed bounded synthetic fixture corpus.'),'pcs-manager-admin','["*"]');
END $helper$;
DO $qa$
DECLARE brand uuid; actor uuid:=gen_random_uuid(); target uuid; post uuid; post2 uuid; job uuid; claim uuid; cmd jsonb; p jsonb; schedule_cmd jsonb; saved jsonb; result jsonb; receipt jsonb; v integer; target_v integer:=1; denied boolean; future text; bad jsonb;
BEGIN
 INSERT INTO neon_auth."user"(id,name,email,"emailVerified","createdAt","updatedAt",banned) VALUES(actor,'QA publication queue','qa-queue-'||actor||'@example.invalid',false,now(),now(),false);PERFORM pcs.staff_manage(actor,'OPS_ADMIN',true);
 p:=pcs.content_action('brand',jsonb_build_object('request_id',gen_random_uuid(),'name','QA publication queue','guidelines','Only confirmed fixture facts. Do not publish real material.'),'pcs-manager-admin','["*"]');brand:=(p#>>'{brand,id}')::uuid;
 p:=pcs.content_target_action(jsonb_build_object('request_id',gen_random_uuid(),'brand_id',brand,'username','qa_queue_channel'),'pcs-manager-admin','["*"]','{"username":"qa_queue_channel","chat_id":"-100111222333","bot_id":"123456789","title":"Synthetic queue channel","can_post_messages":true}');target:=(p->>'id')::uuid;
 p:=pg_temp.qa_queue_post(brand);post:=(p->>'id')::uuid;v:=(p->>'version')::integer;future:=to_char(timezone('UTC',clock_timestamp()+interval '1 day'),'YYYY-MM-DD"T"HH24:MI:SS.US"Z"');
 cmd:=jsonb_build_object('request_id',gen_random_uuid(),'id',post,'expected_version',v,'target_id',target,'target_version',target_v,'scheduled_at',future,'publication_confirmed',true);
 FOR bad IN SELECT * FROM jsonb_array_elements(jsonb_build_array(cmd-'publication_confirmed',cmd||'{"publication_confirmed":false}',cmd||'{"scheduled_at":"2099-01-01T12:00:00"}',cmd||'{"target_version":99}')) LOOP
  denied:=false;BEGIN PERFORM pcs.content_publication_action('schedule',bad,actor::text,'[]');EXCEPTION WHEN invalid_parameter_value OR serialization_failure THEN denied:=true;END;IF NOT denied THEN RAISE EXCEPTION 'QA invalid schedule accepted';END IF;
 END LOOP;
 saved:=pcs.content_publication_action('schedule',cmd,actor::text,'[]');job:=(saved#>>'{job,id}')::uuid;v:=(saved->>'version')::integer;schedule_cmd:=cmd;
 IF saved->>'status'<>'READY' OR saved#>>'{job,state}'<>'QUEUED' OR saved#>>'{job,body}'<>'Approved queue fixture text' OR saved#>>'{job,chat_id}'<>'-100111222333' THEN RAISE EXCEPTION 'QA schedule lost approved snapshot';END IF;
 p:=pcs.content_publication_action('schedule',cmd,actor::text,'[]');IF p->>'replayed'<>'true' OR p-'replayed'<>saved OR (SELECT count(*) FROM pcs.content_publication_jobs WHERE post_id=post)<>1 THEN RAISE EXCEPTION 'QA schedule retry duplicated job';END IF;
 PERFORM pcs.staff_manage(actor,'AUDITOR_READONLY',true);denied:=false;BEGIN PERFORM pcs.content_publication_action('schedule',cmd,actor::text,'["*"]');EXCEPTION WHEN insufficient_privilege THEN denied:=true;END;IF NOT denied THEN RAISE EXCEPTION 'QA revoked schedule receipt allowed';END IF;PERFORM pcs.staff_manage(actor,'OPS_ADMIN',true);
 UPDATE neon_auth."user" SET banned=true WHERE id=actor;denied:=false;BEGIN PERFORM pcs.content_publication_action('schedule',cmd,actor::text,'["*"]');EXCEPTION WHEN insufficient_privilege THEN denied:=true;END;IF NOT denied THEN RAISE EXCEPTION 'QA banned schedule receipt allowed';END IF;UPDATE neon_auth."user" SET banned=false WHERE id=actor;
 denied:=false;BEGIN PERFORM pcs.content_action('schedule',jsonb_build_object('request_id',gen_random_uuid(),'id',post,'expected_version',v,'scheduled_at',future),'pcs-manager-admin','["*"]');EXCEPTION WHEN serialization_failure THEN denied:=true;END;IF NOT denied THEN RAISE EXCEPTION 'QA legacy plan bypassed queued lock';END IF;
 p:=pcs.content_publication_action('cancel',jsonb_build_object('request_id',gen_random_uuid(),'id',post,'expected_version',v,'job_id',job),actor::text,'[]');v:=(p->>'version')::integer;
 IF p->>'status'<>'APPROVED' OR p#>>'{job,state}'<>'CANCELLED' OR EXISTS(SELECT 1 FROM pcs.content_posts WHERE id=post AND (scheduled_at IS NOT NULL OR publication_target_id IS NOT NULL)) THEN RAISE EXCEPTION 'QA cancellation not safe';END IF;
 cmd:=schedule_cmd||jsonb_build_object('request_id',gen_random_uuid(),'expected_version',v);p:=pcs.content_publication_action('schedule',cmd,actor::text,'[]');v:=(p->>'version')::integer;
 IF p#>>'{job,id}'<>job::text THEN RAISE EXCEPTION 'QA unsent reschedule allocated second job';END IF;
 -- Revise cancels an unsent job atomically and clears approval.
 p:=pcs.content_action('revise',jsonb_build_object('request_id',gen_random_uuid(),'id',post,'expected_version',v,'platform','telegram','language','en','title','Revised fixture','body','A revised fixture text','source_facts','Confirmed fixture business facts for this revision.','source_url','https://example.invalid/queue'),'pcs-manager-admin','["*"]');
 IF p->>'status'<>'DRAFT' OR NOT EXISTS(SELECT 1 FROM pcs.content_publication_jobs WHERE id=job AND state='CANCELLED') THEN RAISE EXCEPTION 'QA revise did not cancel queued job';END IF;
 -- A separate exact revision exercises worker delivery and SENT receipt validation.
 p:=pg_temp.qa_queue_post(brand);post2:=(p->>'id')::uuid;v:=(p->>'version')::integer;cmd:=schedule_cmd||jsonb_build_object('request_id',gen_random_uuid(),'id',post2,'expected_version',v);p:=pcs.content_publication_action('schedule',cmd,actor::text,'[]');job:=(p#>>'{job,id}')::uuid;v:=(p->>'version')::integer;
 UPDATE pcs.content_publication_jobs SET scheduled_at=clock_timestamp()-interval '1 minute' WHERE id=job;
 ALTER TABLE pg_temp.audit_events ADD CONSTRAINT qa_claim_audit_failure CHECK(action<>'content.publication.claim') NOT VALID;
 denied:=false;BEGIN PERFORM pcs.content_claim_publication();EXCEPTION WHEN check_violation THEN denied:=true;END;IF NOT denied THEN RAISE EXCEPTION 'QA claim audit failure ignored';END IF;
 IF NOT EXISTS(SELECT 1 FROM pcs.content_publication_jobs WHERE id=job AND state='QUEUED' AND claim_id IS NULL) THEN RAISE EXCEPTION 'QA claim audit failure leaked claim';END IF;ALTER TABLE pg_temp.audit_events DROP CONSTRAINT qa_claim_audit_failure;
 p:=pcs.content_claim_publication();claim:=(p#>>'{job,claim_id}')::uuid;IF p#>>'{job,id}'<>job::text OR p#>>'{job,state}'<>'SENDING' OR claim IS NULL THEN RAISE EXCEPTION 'QA claim lost exact job';END IF;
 IF pcs.content_claim_publication()->'job'<>'null'::jsonb THEN RAISE EXCEPTION 'QA SENDING reclaimed automatically';END IF;
 denied:=false;BEGIN PERFORM pcs.content_action('brand',jsonb_build_object('request_id',gen_random_uuid(),'id',brand,'expected_version',1,'name','Changed during dispatch','guidelines','These changed rules must never race an external send.'),'pcs-manager-admin','["*"]');EXCEPTION WHEN serialization_failure THEN denied:=true;END;IF NOT denied THEN RAISE EXCEPTION 'QA SENDING brand rules changed';END IF;
 IF NOT EXISTS(SELECT 1 FROM pcs.content_brands WHERE id=brand AND version=1 AND name='QA publication queue') THEN RAISE EXCEPTION 'QA rejected brand update leaked';END IF;
 denied:=false;BEGIN PERFORM pcs.content_target_action(jsonb_build_object('request_id',gen_random_uuid(),'brand_id',brand,'username','qa_queue_channel','id',target,'expected_version',1),'pcs-manager-admin','["*"]','{"username":"qa_queue_channel","chat_id":"-100111222333","bot_id":"123456789","title":"Changed during dispatch","can_post_messages":true}');EXCEPTION WHEN serialization_failure THEN denied:=true;END;IF NOT denied THEN RAISE EXCEPTION 'QA SENDING target identity changed';END IF;
 IF NOT EXISTS(SELECT 1 FROM pcs.content_targets WHERE id=target AND version=1 AND title='Synthetic queue channel') THEN RAISE EXCEPTION 'QA rejected target update leaked';END IF;
 denied:=false;BEGIN PERFORM pcs.content_action('report-publication',jsonb_build_object('request_id',gen_random_uuid(),'id',post2,'expected_version',v,'publication_url','https://example.invalid/fake','publication_note','Must not replace a pending external transport.'),'pcs-manager-admin','["*"]');EXCEPTION WHEN serialization_failure THEN denied:=true;END;IF NOT denied THEN RAISE EXCEPTION 'QA SENDING manual report accepted';END IF;
 result:=jsonb_build_object('outcome','SENT','chat_id','-100111222333','text','Approved queue fixture text','message_id','42','date',floor(extract(epoch FROM clock_timestamp()))::bigint);
 FOR bad IN SELECT * FROM jsonb_array_elements(jsonb_build_array(result||'{"chat_id":"-100000000000"}',result||'{"text":"Changed body"}',result||'{"message_id":"0"}',result||'{"date":9007199254740992}',result||'{"reason":"secret"}')) LOOP
  denied:=false;BEGIN PERFORM pcs.content_complete_publication(job,claim,bad);EXCEPTION WHEN invalid_parameter_value THEN denied:=true;END;IF NOT denied THEN RAISE EXCEPTION 'QA mismatched provider receipt accepted';END IF;
 END LOOP;
 ALTER TABLE pg_temp.audit_events ADD CONSTRAINT qa_complete_audit_failure CHECK(action<>'content.publication.complete') NOT VALID;
 denied:=false;BEGIN PERFORM pcs.content_complete_publication(job,claim,result);EXCEPTION WHEN check_violation THEN denied:=true;END;IF NOT denied THEN RAISE EXCEPTION 'QA completion audit failure ignored';END IF;
 IF NOT EXISTS(SELECT 1 FROM pcs.content_publication_jobs WHERE id=job AND state='SENDING' AND provider_receipt IS NULL) OR EXISTS(SELECT 1 FROM pcs.content_posts WHERE id=post2 AND status='PUBLICATION_SENT') THEN RAISE EXCEPTION 'QA completion audit failure leaked receipt';END IF;ALTER TABLE pg_temp.audit_events DROP CONSTRAINT qa_complete_audit_failure;
 receipt:=pcs.content_complete_publication(job,claim,result);IF receipt#>>'{job,state}'<>'SENT' OR receipt#>>'{job,public_url}'<>'https://t.me/qa_queue_channel/42' OR NOT EXISTS(SELECT 1 FROM pcs.content_posts WHERE id=post2 AND status='PUBLICATION_SENT') THEN RAISE EXCEPTION 'QA SENT receipt not canonical';END IF;
 SELECT version INTO v FROM pcs.content_posts WHERE id=post2;p:=pcs.content_verify_publication(jsonb_build_object('request_id',gen_random_uuid(),'id',post2,'expected_version',v),'pcs-manager-admin','["*"]');IF p->>'verification_required'<>'true' THEN RAISE EXCEPTION 'QA SENT verification unavailable';END IF;
 p:=pcs.content_complete_publication(job,claim,result);IF p->>'replayed'<>'true' THEN RAISE EXCEPTION 'QA completion replay failed';END IF;
 denied:=false;BEGIN PERFORM pcs.content_complete_publication(job,claim,'{"outcome":"UNKNOWN","reason":"transport_unknown"}');EXCEPTION WHEN serialization_failure THEN denied:=true;END;IF NOT denied THEN RAISE EXCEPTION 'QA terminal receipt changed';END IF;
 SELECT version INTO v FROM pcs.content_posts WHERE id=post2;denied:=false;BEGIN PERFORM pcs.content_action('submit',jsonb_build_object('request_id',gen_random_uuid(),'id',post2,'expected_version',v),'pcs-manager-admin','["*"]');EXCEPTION WHEN serialization_failure THEN denied:=true;END;IF NOT denied THEN RAISE EXCEPTION 'QA SENT content unlocked';END IF;
 -- UNKNOWN is terminal for automatic work and freezes the exact post.
 p:=pg_temp.qa_queue_post(brand);post2:=(p->>'id')::uuid;v:=(p->>'version')::integer;cmd:=schedule_cmd||jsonb_build_object('request_id',gen_random_uuid(),'id',post2,'expected_version',v);p:=pcs.content_publication_action('schedule',cmd,actor::text,'[]');job:=(p#>>'{job,id}')::uuid;v:=(p->>'version')::integer;UPDATE pcs.content_publication_jobs SET scheduled_at=clock_timestamp()-interval '1 minute' WHERE id=job;
 p:=pcs.content_claim_publication();claim:=(p#>>'{job,claim_id}')::uuid;PERFORM pcs.content_complete_publication(job,claim,'{"outcome":"UNKNOWN","reason":"transport_unknown"}');
 IF pcs.content_claim_publication()->'job'<>'null'::jsonb THEN RAISE EXCEPTION 'QA UNKNOWN auto retry occurred';END IF;
 denied:=false;BEGIN PERFORM pcs.content_publication_action('cancel',jsonb_build_object('request_id',gen_random_uuid(),'id',post2,'expected_version',v,'job_id',job),actor::text,'[]');EXCEPTION WHEN serialization_failure THEN denied:=true;END;IF NOT denied THEN RAISE EXCEPTION 'QA UNKNOWN cancellation accepted';END IF;
 denied:=false;BEGIN PERFORM pcs.content_action('submit',jsonb_build_object('request_id',gen_random_uuid(),'id',post2,'expected_version',v),'pcs-manager-admin','["*"]');EXCEPTION WHEN serialization_failure THEN denied:=true;END;IF NOT denied THEN RAISE EXCEPTION 'QA UNKNOWN content unlocked';END IF;
 -- REJECTED and BLOCKED are definitely unsent, reusable only by explicit schedule.
 p:=pg_temp.qa_queue_post(brand);post2:=(p->>'id')::uuid;v:=(p->>'version')::integer;cmd:=schedule_cmd||jsonb_build_object('request_id',gen_random_uuid(),'id',post2,'expected_version',v);p:=pcs.content_publication_action('schedule',cmd,actor::text,'[]');job:=(p#>>'{job,id}')::uuid;UPDATE pcs.content_publication_jobs SET scheduled_at=clock_timestamp()-interval '1 minute' WHERE id=job;
 p:=pcs.content_claim_publication();claim:=(p#>>'{job,claim_id}')::uuid;PERFORM pcs.content_complete_publication(job,claim,'{"outcome":"REJECTED","reason":"target_preflight_failed"}');
 SELECT version INTO v FROM pcs.content_posts WHERE id=post2;cmd:=schedule_cmd||jsonb_build_object('request_id',gen_random_uuid(),'id',post2,'expected_version',v);p:=pcs.content_publication_action('schedule',cmd,actor::text,'[]');IF p#>>'{job,id}'<>job::text THEN RAISE EXCEPTION 'QA rejected reschedule duplicated job';END IF;
 UPDATE pcs.content_targets SET version=version+1 WHERE id=target;UPDATE pcs.content_publication_jobs SET scheduled_at=clock_timestamp()-interval '1 minute' WHERE id=job;
 p:=pcs.content_claim_publication();IF p->'job'<>'null'::jsonb OR p->>'blocked_job_id'<>job::text OR NOT EXISTS(SELECT 1 FROM pcs.content_publication_jobs WHERE id=job AND state='BLOCKED' AND last_error='target_changed') THEN RAISE EXCEPTION 'QA changed target not blocked';END IF;
 IF has_function_privilege('public','pcs.content_publication_action(text,jsonb,text,jsonb)','EXECUTE') OR has_function_privilege('public','pcs.content_claim_publication()','EXECUTE') OR has_function_privilege('public','pcs.content_complete_publication(uuid,uuid,jsonb)','EXECUTE') OR has_table_privilege('public','pcs.content_publication_jobs','SELECT,INSERT,UPDATE,DELETE') THEN RAISE EXCEPTION 'QA queue PUBLIC access';END IF;
END $qa$;
